	// per 2x2 group of every reference's latents on top of the user's text.
	encTokens := opt.MaxPrompt + p.refs*p.condTokens/4
	if p.enc, err = qwen.NewGPUEncoder(dev, set, tcfg, tcfg.NumLayers, encTokens, nil); err != nil {
