package vae

import "testing"

// Scratch probe: is the decoder's arena a function of area, or of the sides?
func TestArenaShapes(t *testing.T) {
	_, dec := loadCPU(t)
	shapes := [][2]int{
		{1024, 1024},
		{1344, 768}, {1376, 768}, {1216, 832}, {1152, 896},
		{512, 2048}, {2048, 512}, {256, 4096},
		{1184, 1184}, {1568, 896}, {1600, 896}, {1536, 864}, {1664, 928},
		{1920, 1088}, {2048, 1152}, {2048, 2048},
	}
	for _, s := range shapes {
		w, h := s[0], s[1]
		n, err := ArenaBytes(dec, h/16, w/16)
		if err != nil {
			t.Fatal(err)
		}
		verdict := "fits"
		if n > MaxStorageBufferBytes {
			verdict = "OVER"
		}
		mpx := float64(w*h) / 1e6
		t.Logf("%4dx%-4d  %6.3f Mpx  tokens %5d  arena %6d MB  %6.1f B/px  %s",
			w, h, mpx, (w/16)*(h/16), n>>20, float64(n)/float64(w*h), verdict)
	}
}

