44	func (f *fakeImage) Generate(_ context.Context, req *ImageRequest) (*ImageResult, error) {
45		f.reqs = append(f.reqs, *req)
46		if f.err != nil {
47			return nil, f.err
48		}
49		// The partials, which a real backend picks the steps for. This one sends
50		// exactly as many as were asked for, so the handler's framing is what is
51		// under test rather than the schedule's spacing.
52		if req.Partial != nil && req.PartialImages > 0 {
53			steps := req.Steps
54			if steps == 0 {
55				steps = f.Geometry().Steps
56			}
57			for i := 0; i < req.PartialImages; i++ {
