49	func loadCPU(t *testing.T) (*Config, *Decoder) {
50		t.Helper()
51		cfg, err := LoadConfig(vaeDir)
52		if err != nil {
53			t.Skipf("no VAE checkpoint at %s (%v)", vaeDir, err)
54		}
