62	// loadGPU loads the decoder and builds its device graph for one latent size.
63	//
64	// The cleanup is registered rather than deferred by the caller, and the
65	// device's teardown has to be registered the same way and *first*: cleanups
66	// run last-in-first-out and after every deferred call in the test body, so a
67	// deferred dev.Destroy() would free the device out from under these
68	// pipelines and the shim would segfault destroying them.
69	func loadGPU(t *testing.T, dev *vk.Device, h, w int) (*Config, *Decoder, *GPUDecoder) {
70		t.Helper()
71		cfg, dec := loadCPU(t)
72		g, err := NewGPUDecoder(dev, dec, h, w)
73		if err != nil {
74			t.Fatal(err)
75		}
76		t.Cleanup(g.Destroy)
77		return cfg, dec, g
78	}
