80	// TestGPUDecoderStages walks the device graph stage by stage against the same
81	// dump the CPU decoder is gated on — conv_in, the mid block, every up block,
82	// the fused tail norm, conv_out and the clamped image — for both of the
83	// dump's cases. The bounds are vae_test.go's, unchanged: this path is fp32
84	// throughout, so a summation-order difference is all that separates it from
85	// the CPU port, and a structural mistake shows at rel >= 1e-1 on every one
86	// of these stages.
87	func TestGPUDecoderStages(t *testing.T) {
88		m := loadManifest(t)
89		dev, done := newTestDevice(t)
90		t.Cleanup(done)
91	
92		for label, c := range m.Cases {
93			lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
94			t.Run(label, func(t *testing.T) {
95				cfg, _, g := loadGPU(t, dev, lh, lw)
96				n, err := g.Dispatches(lh, lw)
97				if err != nil {
98					t.Fatal(err)
99				}
100				t.Logf("%s: %d dispatches, %d MB activations, %d MB weights",
101					label, n, g.ActivationBytes()>>20, g.WeightBytes()>>20)
102	
103				z := loadRef(t, m, label+"_z_norm")
104				cfg.Denormalize(z)
105	
106				stages, err := g.Stages(lh, lw)
107				if err != nil {
108					t.Fatal(err)
109				}
110				for _, name := range stages {
111					got, err := g.RunTo(z, name)
112					if err != nil {
113						t.Fatal(err)
114					}
115					compare(t, label+"_dec_"+name, got, loadRef(t, m, label+"_dec_"+name))
116				}
117	
118				img, err := g.Decode(z)
119				if err != nil {
120					t.Fatal(err)
121				}
122				compare(t, label+"_decoded", img, loadRef(t, m, label+"_decoded"))
123			})
124		}
125	}
126	
127	// TestGPUDecoderMatchesCPU is the same decode on both paths, end to end. It
128	// is the tighter instrument of the two: the dump carries the reference's own
129	// fp32 noise, while this isolates what the device graph does differently
130	// from the Go one it was ported from.
131	func TestGPUDecoderMatchesCPU(t *testing.T) {
132		m := loadManifest(t)
133		dev, done := newTestDevice(t)
134		t.Cleanup(done)
135	
136		c, ok := m.Cases["s256"]
137		if !ok {
138			t.Skip("reference has no s256 case")
139		}
140		lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
141		cfg, dec, g := loadGPU(t, dev, lh, lw)
142	
143		z := loadRef(t, m, "s256_z_norm")
144		cfg.Denormalize(z)
145	
146		want, err := dec.Decode(z)
147		if err != nil {
148			t.Fatal(err)
149		}
150		got, err := g.Decode(z)
151		if err != nil {
152			t.Fatal(err)
153		}
154		// Named to land on tolFor's loose bound, and for the reason that bound
155		// exists: this comparison is downstream of the tail norm, where the model
156		// rescales O(1e4) activations to O(1) and any summation-order difference
157		// upstream surfaces elementwise. The number to read is the max abs, in
158		// [-1, 1] — it comes out below the CPU port's own distance from the dump.
159		compare(t, "s256_gpu_vs_cpu_decoded", got, want)
160	}
