162	// TestGPUDecoderNegativeControl breaks the one piece of the graph that is
163	// neither z-image's nor obvious — the up blocks' parameter-free shortcut,
164	// whose channel mapping depends on a temporal factor that no longer has an
165	// axis — and checks the bound catches it. Without it, "the DupUp layout is
166	// right" rests on a stage comparison that could have been passing for the
167	// wrong reason.
168	func TestGPUDecoderNegativeControl(t *testing.T) {
169		m := loadManifest(t)
170		dev, done := newTestDevice(t)
171		t.Cleanup(done)
172	
173		c, ok := m.Cases["s256"]
174		if !ok {
175			t.Skip("reference has no s256 case")
176		}
177		lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
178		cfg, dec := loadCPU(t)
179	
180		// Every temporal factor set to 1: the spatial duplication is unchanged
181		// and only which source channel feeds an output pixel moves.
182		for i := range dec.Ups {
183			if dec.Ups[i].Shortcut != nil {
184				dec.Ups[i].Shortcut.FactorT = 1
185			}
186		}
187		bad, err := NewGPUDecoder(dev, dec, lh, lw)
188		if err != nil {
189			t.Fatal(err)
190		}
191		t.Cleanup(bad.Destroy)
192	
193		z := loadRef(t, m, "s256_z_norm")
194		cfg.Denormalize(z)
195		got, err := bad.Decode(z)
196		if err != nil {
197			t.Fatal(err)
198		}
199		want := loadRef(t, m, "s256_decoded")
200		var rel float64
201		for i := range want.Data {
202			d := math.Abs(float64(got.Data[i]) - float64(want.Data[i]))
203			if r := d / math.Max(math.Abs(float64(want.Data[i])), 1e-3); r > rel {
204				rel = r
205			}
206		}
207		if rel <= normTol {
208			t.Fatalf("temporal factor 1 everywhere still decodes at rel %.3g, inside the %.0e bound", rel, normTol)
209		}
210		t.Logf("negative control (FactorT=1): rel %.3g, %.0fx the bound", rel, rel/normTol)
211	}
